<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {executionApi,projectsApi,reviewsApi,type ExecutionTaskSummary,type AcceptedCase} from '../api'
import {errorMessage,formatDate} from '../utils'
const pid=Number(useRoute().params.projectId),router=useRouter(),name=ref(''),tasks=ref<ExecutionTaskSummary[]>([]),total=ref(0),page=ref(1),loading=ref(false),error=ref('')
const editor=ref(false),cases=ref<AcceptedCase[]>([]),caseLoading=ref(false),saving=ref(false),formError=ref(''),search=ref(''),smoke=ref(false),selected=ref<string[]>([])
const form=ref({name:'',environment:'',executor:'',note:'',acknowledge_outdated:false})
const dirty=computed(()=>editor.value&&(selected.value.length>0||Object.values(form.value).some(v=>v!==''&&v!==false)))
const filtered=computed(()=>cases.value.filter(item=>(!smoke.value||item.is_smoke)&&`${item.title} ${item.requirement_title} ${item.module} ${item.feature_name}`.toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase())))
const outdatedCount=computed(()=>cases.value.filter(item=>selected.value.includes(item.id)&&item.outdated).length)
let pending:{signature:string;id:string}|undefined
async function load(){loading.value=true;error.value='';try{const[p,result]=await Promise.all([projectsApi.get(pid),executionApi.list(pid,(page.value-1)*20)]);name.value=p.name;tasks.value=result.items;total.value=result.total}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function open(){editor.value=true;form.value={name:'',environment:'',executor:'',note:'',acknowledge_outdated:false};selected.value=[];search.value='';smoke.value=false;pending=undefined;formError.value='';caseLoading.value=true;try{cases.value=await reviewsApi.accepted(pid)}catch(e){formError.value=errorMessage(e)}finally{caseLoading.value=false}}
async function discard(){if(saving.value)return false;if(!dirty.value)return true;try{await ElMessageBox.confirm('放弃尚未保存的执行任务配置？','未保存的任务',{type:'warning',confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});return true}catch{return false}}
async function close(done:()=>void){if(await discard()){editor.value=false;done()}}
async function create(){if(saving.value)return;saving.value=true;formError.value='';try{if(!selected.value.length||selected.value.length>200)throw Error('请选择 1–200 条已采纳用例。');const data={...form.value,name:form.value.name.trim(),environment:form.value.environment.trim(),executor:form.value.executor.trim(),note:form.value.note.trim(),case_ids:[...selected.value]};if(!data.name||!data.environment)throw Error('请填写任务名称和执行环境。');const signature=JSON.stringify(data);if(!pending||pending.signature!==signature)pending={signature,id:crypto.randomUUID()};const task=await executionApi.create(pid,{...data,task_id:pending.id});editor.value=false;saving.value=false;await router.push(`/projects/${pid}/execution-tasks/${task.id}`)}catch(e){formError.value=errorMessage(e)+' 提交结果不明时，请先关闭编辑器并刷新任务列表核实。'}finally{saving.value=false}}
function selectFiltered(){selected.value=[...new Set([...selected.value,...filtered.value.map(item=>item.id)])].slice(0,200)}
function unload(event:BeforeUnloadEvent){if(dirty.value||saving.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(discard);onBeforeRouteUpdate(discard);onMounted(()=>{window.addEventListener('beforeunload',unload);void load()});onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
</script>
<template><main><router-link :to="`/projects/${pid}/testcases`" class="back-link">← 已采纳用例</router-link><div class="page-heading"><div><div class="eyebrow">MANUAL TEST EXECUTION</div><h1>{{name||'项目'}} · 人工执行任务</h1><p>从已采纳用例创建固定快照，人工执行后记录结果。</p></div><div><el-button :loading="loading" @click="load">刷新</el-button><el-button type="primary" :disabled="loading" @click="open">创建执行任务</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<section class="project-panel"><div class="panel-toolbar"><h2>共 {{total}} 个任务</h2><span class="field-help">无模型调用，无自动化脚本执行</span></div><div class="draft-panel-body"><article v-for="task in tasks" :key="task.id" class="case-card"><div class="case-card-title"><h3><router-link :to="`/projects/${pid}/execution-tasks/${task.id}`">{{task.name}}</router-link></h3><el-tag :type="task.status==='completed'?'success':'info'">{{task.status==='completed'?'已结束':'记录中'}}</el-tag></div><p class="execution-text">环境：{{task.environment}}</p><p class="field-help">{{task.executor||'未填写执行人'}} · 创建 {{formatDate(task.created_at)}} · {{task.stats.recorded}} / {{task.stats.total}} 条已记录</p><p>通过 {{task.stats.passed}} · 失败 {{task.stats.failed}} · 阻塞 {{task.stats.blocked}} · 未执行 {{task.stats.not_run}}</p><router-link :to="`/projects/${pid}/execution-tasks/${task.id}`" class="row-link">查看并记录结果 →</router-link></article><el-empty v-if="!tasks.length&&!loading" description="还没有执行任务，先采纳用例再创建任务"/></div><el-pagination v-if="total>20" v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" :disabled="loading" @current-change="load"/></section>
<el-dialog v-model="editor" title="创建人工执行任务" width="min(860px,95vw)" :close-on-click-modal="false" :before-close="close"><el-alert title="任务保存的是本次用例快照；来源修改或删除不会改变历史内容。Mock 用例仍会带来源标记，人工执行结果不等于自动化运行证明。" type="info" :closable="false"/><el-form :disabled="saving||caseLoading" label-position="top"><el-form-item label="任务名称（必填）"><el-input v-model="form.name" maxlength="100" aria-label="执行任务名称"/></el-form-item><el-form-item label="执行环境 / 版本（必填）"><el-input v-model="form.environment" maxlength="500" aria-label="执行环境" placeholder="例如：测试环境 · v1.0 · Chrome"/></el-form-item><el-form-item label="执行人（选填）"><el-input v-model="form.executor" maxlength="80" aria-label="执行人"/></el-form-item><el-form-item label="任务备注"><el-input v-model="form.note" type="textarea" maxlength="2000" :rows="2" aria-label="执行任务备注"/></el-form-item><div class="execution-select-tools"><el-input v-model="search" placeholder="筛选标题、需求或功能点" clearable aria-label="筛选执行用例"/><el-checkbox v-model="smoke">仅冒烟</el-checkbox><el-button :disabled="saving||caseLoading" @click="selectFiltered">选中当前筛选（最多 200 条）</el-button><el-button @click="selected=[]">清空选择</el-button></div><p>已选 {{selected.length}} 条 · 当前筛选 {{filtered.length}} 条 · 已知依据过期 {{outdatedCount}} 条</p><el-checkbox-group v-model="selected" :max="200" class="execution-case-picker"><article v-for="item in filtered" :key="item.id"><el-checkbox :value="item.id"><span>{{item.title}}</span></el-checkbox><p class="field-help">{{item.requirement_title}} / {{item.feature_name}} · {{item.priority}} <span v-if="item.is_smoke">· 冒烟</span><span v-if="item.source==='mock'"> · Mock 示例</span><span v-if="item.outdated"> · 生成依据已变化</span></p></article></el-checkbox-group><el-empty v-if="!filtered.length&&!caseLoading" description="没有可选用例，请先在草稿页采纳用例或调整筛选"/><el-checkbox v-model="form.acknowledge_outdated">已人工核对依据过期用例的适用性，仍允许纳入本任务</el-checkbox><p class="field-help">后端会重新检查采纳状态和生成依据，页面选择不直接作为授权。</p></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button :disabled="saving" @click="close(()=>editor=false)">取消</el-button><el-button type="primary" :loading="saving" :disabled="caseLoading||!selected.length" @click="create">保存快照并创建任务</el-button></template></el-dialog></main></template>
<style scoped>.execution-text{white-space:pre-wrap;overflow-wrap:anywhere}.execution-select-tools{display:flex;gap:12px;flex-wrap:wrap}.execution-select-tools .el-input{width:230px}.execution-case-picker{max-height:350px;overflow:auto;border:1px solid #e4eaf1;padding:12px;margin-bottom:18px}.execution-case-picker article+article{border-top:1px solid #e4eaf1;padding-top:8px}.execution-case-picker .el-checkbox{height:auto;white-space:normal}.execution-case-picker :deep(.el-checkbox__label){white-space:normal}.el-form{margin-top:16px}.el-pagination{padding:20px}</style>
